<?php declare(strict_types=1); /** @var Closure(mixed): string $escape */ $required='<span class="required-mark">*</span>'; ?>
<span class="status">CRM · <?= $escape($unit['name']) ?></span><h1>Novo follow-up</h1><p>Contato: <strong><?= $escape($contact['name']) ?></strong></p>
