<form method="post" action="<?= $escape($basePath) ?>/crm/contacts/<?= $escape($contact['id']) ?>/follow-ups"><?= $csrfField ?><label>Próxima ação <?= $required ?><input name="action" required minlength="2" maxlength="160" placeholder="Ex.: Retornar por WhatsApp"></label><div class="row"><div class="col-sm-6"><label>Data e hora <?= $required ?><input name="scheduled_at" type="datetime-local" required value="<?= $escape(date('Y-m-d\TH:i',strtotime('+1 day'))) ?>"></label></div><div class="col-sm-6"><label>Atendente <?= $required ?><select class="form-select" name="responsible_user_id" required><?php foreach($responsibles as $person):?><option value="<?= $escape($person['id']) ?>" <?= (int)$selectedResponsibleId===(int)$person['id']?'selected':'' ?>><?= $escape($person['name']) ?></option><?php endforeach;?></select></label></div></div><label>Observações <?= $required ?><textarea name="notes" required minlength="2" maxlength="5000" rows="4"></textarea></label><button type="submit">Salvar follow-up</button></form><p><a href="<?= $escape($basePath) ?>/crm/contacts">Cancelar</a></p>
<?php if($history!==[]):?><h2>Histórico do contato</h2><div class="table-responsive"><table><thead><tr><th>Data/Hora</th><th>Ação</th><th>Atendente</th><th>Situação</th></tr></thead><tbody><?php foreach($history as $item):?><tr><td><?= $escape(date('d/m/Y H:i',strtotime((string)$item['scheduled_at']))) ?></td><td><?= $escape($item['action']) ?></td><td><?= $escape($item['responsible_name']) ?></td><td><?= $escape($item['status']) ?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
